with a as(select * from public.authors where open_library_id=any(array['OL42200A','OL1450411A','OL8715660A']::text[]) or id=any(array[3503,3270,710]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789029505130','9789029092722','9789025445874','9789025441869','9789020412345']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL20244922W','OL20934335W','OL22945506W','OL23161111W','OL23233100W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['aanopenzee','14juillet','14juli','enalweerblevenweongedeerd','opstaanaankledennietdoodgaan','leukzegdoei']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['aanopenzee','14juillet','14juli','enalweerblevenweongedeerd','opstaanaankledennietdoodgaan','leukzegdoei']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987160001 and 987160999),'editions',(select count(*) from public.editions where id between 987260001 and 987260999),'authors',(select count(*) from public.authors where id between 987360001 and 987360999))) as preflight;
